@using sv_698184e6f571491aace316f1167768c5.Components.Chat
@inject IJSRuntime JS
@implements IAsyncDisposable

<div class="message-area">
    <div class="message-area-header">
        <h2># @ChannelName</h2>
        <span class="channel-desc">@ChannelDescription</span>
    </div>

    <div class="message-list" @ref="_messageListRef">
        @if (IsLoadingMore)
        {
            <div class="loading-indicator">Loading older messages…</div>
        }
        else if (HasMoreMessages)
        {
            <div class="load-more-sentinel" @ref="_sentinelRef"></div>
        }

        @foreach (var message in Messages)
        {
            @if (message.ReplyToId is null)
            {
                var replyCount = ThreadReplyCounts.GetValueOrDefault(message.Id);
                <MessageItem Message="message"
                             ThreadReplyCount="replyCount"
                             OnOpenThread="OnOpenThread"
                             OnReact="OnReact" />
            }
        }
    </div>

    <MessageInput Placeholder="@($"Message #{ChannelName}")"
                  ButtonLabel="Send"
                  OnSubmit="OnSendMessage" />
</div>

@code {
    [Parameter] public string ChannelName { get; set; } = "";
    [Parameter] public string ChannelDescription { get; set; } = "";
    [Parameter] public List<Message> Messages { get; set; } = [];
    [Parameter] public Dictionary<int, int> ThreadReplyCounts { get; set; } = [];
    [Parameter] public bool HasMoreMessages { get; set; }
    [Parameter] public bool IsLoadingMore { get; set; }
    [Parameter] public EventCallback OnLoadMore { get; set; }
    [Parameter] public EventCallback<int> OnOpenThread { get; set; }
    [Parameter] public EventCallback<(int MessageId, string Emoji)> OnReact { get; set; }
    [Parameter] public EventCallback<string> OnSendMessage { get; set; }

    private ElementReference _messageListRef;
    private ElementReference _sentinelRef;
    private IJSObjectReference? _jsModule;
    private DotNetObjectReference<MessageArea>? _dotNetRef;

    protected override async Task OnAfterRenderAsync(bool firstRender)
    {
        if (firstRender)
        {
            _jsModule = await JS.InvokeAsync<IJSObjectReference>(
                "import", "./_content/sv-698184e6f571491aace316f1167768c5/Components/Chat/MessageArea.razor.js");
            _dotNetRef = DotNetObjectReference.Create(this);
            await _jsModule.InvokeVoidAsync("initScrollObserver", _messageListRef, _dotNetRef);
        }

        // Auto-scroll to bottom when new messages arrive and user is near bottom
        if (_jsModule is not null)
        {
            await _jsModule.InvokeVoidAsync("scrollToBottomIfNeeded", _messageListRef);
        }
    }

    [JSInvokable]
    public async Task OnScrolledToTop()
    {
        if (HasMoreMessages && !IsLoadingMore)
        {
            await OnLoadMore.InvokeAsync();
        }
    }

    public async ValueTask DisposeAsync()
    {
        if (_jsModule is not null)
        {
            await _jsModule.InvokeVoidAsync("dispose");
            await _jsModule.DisposeAsync();
        }
        _dotNetRef?.Dispose();
    }
}

.message-area {
    display: flex;
    flex-direction: column;
    height: 100%;
    background: #fff;
    overflow: hidden;
}

.message-area-header {
    padding: 12px 16px;
    border-bottom: 1px solid #e0e0e0;
    flex-shrink: 0;
}

.message-area-header h2 {
    margin: 0;
    font-size: 1.1rem;
    font-weight: 700;
    color: #1a1a1a;
}

.channel-desc {
    font-size: 0.8rem;
    color: #888;
}

.message-list {
    flex: 1;
    overflow-y: auto;
    padding: 8px 0;
}

.loading-indicator {
    text-align: center;
    padding: 12px;
    color: #888;
    font-size: 0.85rem;
}

.load-more-sentinel {
    height: 1px;
}

let observer = null;
let dotNetRef = null;

export function initScrollObserver(messageList, dotNetReference) {
    dotNetRef = dotNetReference;

    observer = new IntersectionObserver(
        (entries) => {
            for (const entry of entries) {
                if (entry.isIntersecting) {
                    dotNetRef.invokeMethodAsync("OnScrolledToTop");
                }
            }
        },
        { root: messageList, threshold: 0.1 }
    );

    // Observe the sentinel element if it exists
    const sentinel = messageList.querySelector(".load-more-sentinel");
    if (sentinel) {
        observer.observe(sentinel);
    }
}

export function scrollToBottomIfNeeded(messageList) {
    if (!messageList) return;
    const threshold = 150;
    const isNearBottom =
        messageList.scrollHeight - messageList.scrollTop - messageList.clientHeight < threshold;
    if (isNearBottom) {
        messageList.scrollTop = messageList.scrollHeight;
    }
}

export function dispose() {
    if (observer) {
        observer.disconnect();
        observer = null;
    }
    dotNetRef = null;
}

