let observer = null;
let dotNetRef = null;

export function initScrollObserver(messageList, dotNetReference) {
    dotNetRef = dotNetReference;

    observer = new IntersectionObserver(
        (entries) => {
            for (const entry of entries) {
                if (entry.isIntersecting) {
                    dotNetRef.invokeMethodAsync("OnScrolledToTop");
                }
            }
        },
        { root: messageList, threshold: 0.1 }
    );

    // Observe the sentinel element if it exists
    const sentinel = messageList.querySelector(".load-more-sentinel");
    if (sentinel) {
        observer.observe(sentinel);
    }
}

export function scrollToBottomIfNeeded(messageList) {
    if (!messageList) return;
    const threshold = 150;
    const isNearBottom =
        messageList.scrollHeight - messageList.scrollTop - messageList.clientHeight < threshold;
    if (isNearBottom) {
        messageList.scrollTop = messageList.scrollHeight;
    }
}

export function dispose() {
    if (observer) {
        observer.disconnect();
        observer = null;
    }
    dotNetRef = null;
}

